import { ConflictError } from '../errors/DomainError';
import { DueDate } from '../value-objects/DueDate';
import { TaskStatus } from '../value-objects/TaskStatus';
import { TaskTitle } from '../value-objects/TaskTitle';

export interface NewTaskProps {
  id: string;
  projectId: string;
  title: TaskTitle;
  description: string;
  dueDate?: DueDate;
  status?: TaskStatus;
}

export class Task {
  private constructor(
    readonly id: string,
    readonly projectId: string,
    readonly title: TaskTitle,
    readonly description: string,
    readonly dueDate: DueDate | undefined,
    private currentStatus: TaskStatus,
    private currentAssigneeId: string | undefined,
  ) {}

  static create(props: NewTaskProps): Task {
    return new Task(
      props.id,
      props.projectId,
      props.title,
      props.description.trim(),
      props.dueDate,
      props.status ?? TaskStatus.TODO,
      undefined,
    );
  }

  get status(): TaskStatus {
    return this.currentStatus;
  }

  get assigneeId(): string | undefined {
    return this.currentAssigneeId;
  }

  assignTo(userId: string): void {
    this.currentAssigneeId = userId;
  }

  markDone(): void {
    if (this.currentStatus.isDone()) {
      throw new ConflictError(`Task "${this.id}" is already done`);
    }
    this.currentStatus = TaskStatus.DONE;
  }
}

=====SOURCE-END=====

